#include <stdio.h>
#include <string.h>
#include <sys/socket.h>
#include <unistd.h>

int main(void) {
    int fds[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == -1) {
        perror("socketpair");
        return 1;
    }

    const char *msg = "MAYDAY";
    send(fds[0], msg, strlen(msg), 0);

    char buf[32];
    ssize_t got = recv(fds[1], buf, sizeof buf - 1, 0);
    buf[got] = '\0';
    printf("received %zd bytes: %s\n", got, buf);

    close(fds[0]);
    close(fds[1]);
    return 0;
}

