#include <stdio.h>
#include <ctype.h>
#include <string.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>

int main(void) {
    int fds[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == -1) {
        perror("socketpair");
        return 1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {                 // child: the beacon
        close(fds[0]);
        char buf[64];
        ssize_t n = recv(fds[1], buf, sizeof buf, 0);
        for (ssize_t i = 0; i < n; i++) buf[i] = toupper((unsigned char)buf[i]);
        send(fds[1], buf, n, 0);
        close(fds[1]);
        _exit(0);
    }

    close(fds[1]);                  // parent: the station
    const char *msg = "help us";
    send(fds[0], msg, strlen(msg), 0);
    char reply[64];
    ssize_t n = recv(fds[0], reply, sizeof reply - 1, 0);
    reply[n] = '\0';
    waitpid(pid, NULL, 0);
    printf("beacon replied: %s\n", reply);
    close(fds[0]);
    return 0;
}

