#include <stdio.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>

int main(void) {
    int fds[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == -1) {
        perror("socketpair");
        return 1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {                 // server: adds up whatever it's sent
        close(fds[0]);
        int v, total = 0;
        while (recv(fds[1], &v, sizeof v, MSG_WAITALL) == sizeof v) total += v;
        send(fds[1], &total, sizeof total, 0);
        close(fds[1]);
        _exit(0);
    }

    close(fds[1]);                  // client
    int readings[] = { 12, 30, 7 };
    for (int i = 0; i < 3; i++) send(fds[0], &readings[i], sizeof readings[i], 0);
    shutdown(fds[0], SHUT_WR);      // "that's everything"

    int total = 0;
    recv(fds[0], &total, sizeof total, MSG_WAITALL);
    waitpid(pid, NULL, 0);
    printf("server says total = %d\n", total);
    close(fds[0]);
    return 0;
}

