#include <stdio.h>
#include <sys/socket.h>
#include <sys/wait.h>
#include <unistd.h>

void serve(int fd) {
    int v, count = 0, max = 0;
    while (recv(fd, &v, sizeof v, MSG_WAITALL) == sizeof v) {
        if (count == 0 || v > max) max = v;
        count++;
    }
    int reply[2] = { count, max };
    send(fd, reply, sizeof reply, 0);
}

int main(void) {
    int fds[2];
    if (socketpair(AF_UNIX, SOCK_STREAM, 0, fds) == -1) {
        perror("socketpair");
        return 1;
    }

    pid_t pid = fork();
    if (pid == -1) {
        perror("fork");
        return 1;
    }
    if (pid == 0) {
        close(fds[0]);
        serve(fds[1]);
        close(fds[1]);
        _exit(0);
    }

    close(fds[1]);
    int n, v;
    scanf("%d", &n);
    for (int i = 0; i < n; i++) {
        scanf("%d", &v);
        send(fds[0], &v, sizeof v, 0);
    }
    shutdown(fds[0], SHUT_WR);

